-- 실행자: 팀장(Supabase SQL Editor). 워커 초안. 워커 DB 직접 쓰기 금지.
-- 근거 ADR: ADR-0056 (ADR-0056 D1·D2·D4·D5) · Accepted 2026-08-10
-- source 라벨: manifest_txt_v1
-- 이 파일 담당: 48권 / 467행 (정제 후 빈 면 0행 포함 — D7)
-- 생성기: scripts/tts_pilot/gen_book_text_sql_v2.py
-- 매핑: page_index = (P번호|json page) - 1 (0-based, D2/D11). blocks = NULL(원천에 블록 정보 없음).
-- 정제: tts_targets.sanitize() 공유(D6). 표지 행 없음(D3).
-- 인용: $$ 달러 인용. 생성 시 '$$' 포함·'$' 종결 전수 가드 통과.
-- 중복: ON CONFLICT (book_id, page_index) DO NOTHING — 기존 행을 덮어쓰지 않는다.
--
-- ★ 이 파일은 ROLLBACK; 으로 끝난다. [적재검증]까지 기대값과 일치하면
--   마지막 ROLLBACK; 을 COMMIT; 으로 직접 바꿔 타이핑해 확정한다.

-- ───────── [선검증] 트랜잭션 밖 ─────────
-- (a) 대상 권의 기존 book_text 행 수 — 기대 0. 0이 아니면 중단하고 보고할 것.
SELECT count(*) AS rows_before FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('24013', '24014', '2408', '24194', '24215', '24219', '24220', '24340', '24342', '24364', '24387', '24410', '24412', '24444', '24477', '24519', '24532', '24538', '24545', '24557', '24566', '24573', '24580', '24590', '24596', '24617', '24625', '24644', '24647', '24674', '24700', '24729', '24732', '2548', '2549', '2595', '2605', '2940', '3125', '31293', '31355', '31419', '31499', '31578', '31689', '31702', '31708', '31833');
-- (b) 대상 source_id 중 books에 존재하는 권 수 — 기대 48
SELECT count(*) AS books_found FROM books
  WHERE source_platform='african_storybook' AND source_id IN ('24013', '24014', '2408', '24194', '24215', '24219', '24220', '24340', '24342', '24364', '24387', '24410', '24412', '24444', '24477', '24519', '24532', '24538', '24545', '24557', '24566', '24573', '24580', '24590', '24596', '24617', '24625', '24644', '24647', '24674', '24700', '24729', '24732', '2548', '2549', '2595', '2605', '2940', '3125', '31293', '31355', '31419', '31499', '31578', '31689', '31702', '31708', '31833');

